"""Validation Module"""

from __future__ import annotations

import json
import logging
import pprint
import re
import xml.etree.ElementTree as elementTree
from typing import Dict, Hashable, List, Tuple, Union

import xmltodict
from deepdiff import DeepDiff

from taf.internal.rfsw.regexdeepdiff.listmatchoperator import ListMatchOperator


class RegexDeepDiffException(Exception):
    """ValidationException"""


class RegexDeepDiff:
    """Validation class"""

    def __init__(self, logger=None):
        self.logger = logging.getLogger(__name__) if logger is None else logger
        self.last_matched_notification = None

    def validate_output(
        self,
        expected_response: dict | str,
        response: dict | str,
        *,
        validation_mode: str = "deepdiff",
        exclude_paths: None | List[str] = None,
        ignore_dictionary_item_added: bool = False,
        ignore_iterable_item_added: bool = False,
        **kwargs,
    ) -> str:
        """Method to validate output with expected response.

        :param expected_response: Either dict or string with expected results in response.
        :param response: Response that will be validated.
        :param validation_mode: Deepdiff by default, can also be set to string validation.
        :param exclude_paths: Used when validation_mode is deepdiff.
        :param ignore_dictionary_item_added: Ignores additional paths in response.
        :param ignore_iterable_item_added: Ignores additional paths in response.
        :param kwargs:
                force_list - Parameter that will contain tuple or key/value for given child which will be enforced to
                    be kept in list format.
                    Usage: force_list={'edit': True} or force_list=('edit') will force edit to be a list even
                     when it is a single element.
                log_ignored_items - Additional parameter to log ignored items in deepdiff. By default, True.
                log_type_mismatch - Additional parameter to log mismatched items in deepdiff.
                 By default, False.
                exclude_regex_paths: List of path regexes to exclude in deepdiff.
        :return:
        """
        if not exclude_paths:
            exclude_paths = []
        if not isinstance(exclude_paths, list):
            raise ValueError(f"exclude_paths parameter has to be list not {type(exclude_paths)}")
        for exclude_path in exclude_paths:
            if bool(re.search(r'\[\d+\]$', exclude_path)):
                raise RegexDeepDiffException("Paths in exclude_paths cannot end with [number] to avoid inconsistency.")
        if validation_mode == "string":
            return self._validate_output_via_string(expected_response=expected_response, response=response)
        if validation_mode == "deepdiff":
            return self._validate_output_via_deepdiff(
                expected_response=expected_response,
                response=response,
                exclude_paths=exclude_paths,
                ignore_dictionary_item_added=ignore_dictionary_item_added,
                ignore_iterable_item_added=ignore_iterable_item_added,
                **kwargs,
            )
        raise RegexDeepDiffException(f"{validation_mode} is not a supported validation mode.")

    def _validate_output_via_string(self, expected_response: str, response: str) -> str:
        """
        Validates output with verification that output contains expected string.
        :param expected_response: Expected string to be found in response.
        :param response: Response to validate in form of string.
        :return:
        """
        matched = expected_response in response
        if not matched:
            raise RegexDeepDiffException(
                self._create_result_string(response=response, expected=expected_response, matched=False)
            )
        return response

    @staticmethod
    def _process_path(path):
        return path[4:].replace("[", "").replace("'", "").split("]")[:-1]

    @staticmethod
    def _update_expected_response(_expected, _response, level, exp_nokey, rsp_nokey):
        if not level.isdigit():
            if level in _expected and not exp_nokey:
                _expected = _expected[level]
            else:
                exp_nokey = True
            if level in _response and not rsp_nokey:
                _response = _response[level]
            else:
                rsp_nokey = True
        else:
            if isinstance(_expected, list) and int(level) < len(_expected) and not exp_nokey:
                _expected = _expected[int(level)]
            else:
                exp_nokey = True
            if isinstance(_response, list) and int(level) < len(_response) and not rsp_nokey:
                _response = _response[int(level)]
            else:
                rsp_nokey = True
        return _expected, _response, exp_nokey, rsp_nokey

    @staticmethod  # noqa: C901
    def _remove_keys(_expected, _response, path, exp_nokey, rsp_nokey):
        if not path[-1].isdigit():
            exp_nokey = path[-1] not in _expected or exp_nokey
            rsp_nokey = path[-1] not in _response or rsp_nokey
        else:
            if isinstance(_expected, list):
                exp_nokey = int(path[-1]) >= len(_expected) or exp_nokey
            if isinstance(_response, list):
                rsp_nokey = int(path[-1]) >= len(_response) or rsp_nokey
        if not exp_nokey:
            if not path[-1].isdigit():
                _expected.pop(path[-1])
            if isinstance(_expected, list):
                del _expected[int(path[-1])]
        if not rsp_nokey:
            if not path[-1].isdigit():
                _response.pop(path[-1])
            if isinstance(_response, list):
                del _response[int(path[-1])]
        return _expected, _response

    @classmethod
    def _remove_exclude_paths(cls, expected: Dict, response: Dict, exclude_paths: List[str]) -> Tuple[dict, dict]:
        for path in exclude_paths:
            path = cls._process_path(path)
            _expected, _response = expected, response
            exp_nokey, rsp_nokey = False, False
            for level in path[:-1]:
                (
                    _expected,
                    _response,
                    exp_nokey,
                    rsp_nokey,
                ) = cls._update_expected_response(_expected, _response, level, exp_nokey, rsp_nokey)
            _expected, _response = cls._remove_keys(_expected, _response, path, exp_nokey, rsp_nokey)
        return expected, response

    def _deep_sort_mismatch(self, obj):
        if isinstance(obj, dict):
            obj = self._handle_dict_mismatch(obj)
        elif isinstance(obj, list):
            obj = self._handle_list_mismatch(obj)
        return obj

    def _handle_dict_mismatch(self, obj):
        obj = dict(sorted(obj.items()))
        for k, v in obj.items():
            if isinstance(v, (dict, list)):
                obj[k] = self._deep_sort_mismatch(v)
        return obj

    def _handle_list_mismatch(self, obj):
        for i, v in enumerate(obj):
            if isinstance(v, (dict, list)):
                obj[i] = self._deep_sort_mismatch(v)
        obj = sorted(obj, key=lambda x: json.dumps(x))
        return obj

    def _deep_sort(  # noqa: C901
        self,
        expected: Dict,
        response: Union[Dict, List],
        log_type_mismatch: bool,
        exclude_paths: Union[None, List[str]] = None,
    ) -> Tuple:
        if exclude_paths is None:
            exclude_paths = []
        if expected is None and response is None:
            return None, None
        if exclude_paths:
            expected, response = self._remove_exclude_paths(expected, response, exclude_paths)
        if isinstance(expected, dict):
            if not self._check_and_log_type_mismatch(expected, response, log_type_mismatch):
                return None, None
            expected, response = self._handle_dict_sort(expected, response, log_type_mismatch)
        if isinstance(expected, list):
            if not self._check_and_log_type_mismatch(expected, response, log_type_mismatch):
                return None, None
            expected, response = self._handle_list_sort(expected, response, log_type_mismatch)
        return expected, response

    def _check_and_log_type_mismatch(self, expected, response, log_type_mismatch: bool):
        if not isinstance(response, type(expected)):
            if not log_type_mismatch:
                self.logger.debug(
                    "There is a mismatch between expected and response."
                    f"{expected}\nis not the same type as\n{response}.\nUsing old sorting method."
                    "\nPlease consider changing the expected message to match the response."
                )
            return False
        return True

    def _handle_dict_sort(self, expected: Dict, response: Dict, log_type_mismatch: bool) -> Tuple:
        expected, response = dict(sorted(expected.items())), dict(sorted(response.items()))
        for ekv, rkv in zip(expected.items(), response.items()):
            if isinstance(ekv[1], (dict, list)):
                if not self._check_and_log_type_mismatch(ekv[1], rkv[1], log_type_mismatch):
                    return None, None
                expected[ekv[0]], response[rkv[0]] = self._deep_sort(ekv[1], rkv[1], log_type_mismatch)
                if expected[ekv[0]] is None and response[rkv[0]] is None:
                    return None, None
        return expected, response

    def _handle_list_sort(self, expected: List, response: List, log_type_mismatch: bool) -> Tuple:
        # Below code should:
        # -trigger sorting of lists of dictionaries if the types of items in x and y are the same.
        # -handle use case when we have mixed types in lists, and it is expected.
        expected_types = sorted([type(item) for item in expected], key=str)
        response_types = sorted([type(item) for item in response], key=str)
        # Check if the types of items in x and y are the same
        if expected_types == response_types:
            # If the types are exactly the same, we can call in this place _sort_list_of_dicts.
            # If they are not the same, issues should be detected in the next steps.
            expected, response = self._sort_list_of_dicts(expected, response)
        for i, erv in enumerate(zip(expected, response)):
            if isinstance(erv[0], (dict, list)):
                if not self._check_and_log_type_mismatch(erv[0], erv[1], log_type_mismatch):
                    return None, None
                exp, rsp = self._deep_sort(erv[0], erv[1], log_type_mismatch)
                if exp is None and rsp is None:
                    return None, None
                expected[i], response[i] = exp, rsp
        expected, response = self._sort_list_of_dicts(expected, response)
        return expected, response

    @staticmethod  # noqa: C901
    def _sort_list_of_dicts(expected, response) -> Tuple:
        """Method sorts list of dictionaries based on selected key.
        :param expected:
        :param response:
        :return:
        """
        expected_keys = [[*a] for a in expected if isinstance(a, dict)]
        if not expected_keys:
            expected, response = sorted(expected), sorted(response)
        else:
            common_keys = sorted(set.intersection(*map(set, expected_keys)))
            common_keys = [
                b
                for b in common_keys
                for c in expected
                if (not isinstance(c[b], dict) and not isinstance(c[b], list) and c[b] is not None)
            ]
            non_regex = None
            # In this loop we are searching for key which all values:
            # - are not regex
            # - are hashable
            # - are unique among all dicts
            # If a key meets these conditions, it attempts to sort the expected and response lists based on this key.
            # If a TypeError occurs during sorting, it continues to the next key.
            #  Eg: TypeError: '<' not supported between instances of 'dict' and 'str'
            # If sorting is successful, it breaks out of the loop.
            # KeyError is added to handle cases where expected and response lists have different lengths and
            # keys are missing in the response.
            for key in list(common_keys):
                if (
                    sum(["(" in d[key] for d in expected if d[key] is not None]) == 0
                    and all(isinstance(e[key], Hashable) for e in expected)
                    and len({e[key] for e in expected}) == len(expected)
                ):
                    try:
                        expected = sorted(expected, key=lambda x: x[key])
                        response = sorted(response, key=lambda x: x[key])

                        non_regex = key
                        break
                    except (TypeError, KeyError):
                        continue
            if non_regex is None:
                expected = sorted(expected, key=lambda x: json.dumps(x))
                response = sorted(response, key=lambda x: json.dumps(x))
        return expected, response

    @staticmethod
    def _create_custom_operators(ignore_iterable_item_added: bool) -> list:
        custom_operators = None
        if ignore_iterable_item_added:
            custom_operators = [ListMatchOperator()]
        return custom_operators

    def _create_deep_diff(
        self,
        sorted_expected,
        sorted_response,
        expected_response,
        response_dict,
        exclude_paths,
        exclude_regex_paths,
        custom_operators,
    ):
        if sorted_expected is None and sorted_response is None:
            return DeepDiff(
                self._deep_sort_mismatch(expected_response),
                self._deep_sort_mismatch(response_dict),
                exclude_paths=exclude_paths,
                exclude_regex_paths=exclude_regex_paths,
                custom_operators=custom_operators,
            )
        else:
            return DeepDiff(
                sorted_expected,
                sorted_response,
                exclude_regex_paths=exclude_regex_paths,
                custom_operators=custom_operators,
            )

    def _handle_ignored_items(
        self,
        dd_result: dict,
        ignore_dictionary_item_added: bool,
        ignore_iterable_item_added: bool,
        log_ignored_items: bool = True,
    ) -> None:
        """Remove dictionary_item_added or iterable_item_added items from deepdiff result if they are ignored."""
        if ignore_dictionary_item_added and dd_result.get("dictionary_item_added", None):
            ignored_dictionary_items = dd_result.pop("dictionary_item_added", None)
            if log_ignored_items and ignored_dictionary_items:
                self.logger.debug(f"Ignored dictionary items: {ignored_dictionary_items}")
        if ignore_iterable_item_added and dd_result.get("iterable_item_added", None):
            ignored_iterable_items = dd_result.pop("iterable_item_added", None)
            if log_ignored_items and ignored_iterable_items:
                self.logger.debug(f"Ignored iterable items: {ignored_iterable_items}")

    def _validate_output_via_deepdiff(
        self,
        expected_response: dict | str,
        response: dict | str,
        *,
        exclude_paths: None | list[str] = None,
        ignore_dictionary_item_added: bool = False,
        ignore_iterable_item_added: bool = False,
        **kwargs,
    ) -> str:
        """Validates output with deepdiff.

        :param expected_response: Dict representation that will be used for validation reponse.
        :param response: Dict or xml response that will be validated.
        :param exclude_paths: Contains list of paths in output which will be excluded from validation.
        :param ignore_dictionary_item_added: Ignores additional paths in response.
        :param ignore_iterable_item_added: Ignores additional paths in response.
            used also for custom operator to validate lists in response by deepdiff.
        :param kwargs:
            force_list - parameter that will contain tuple or key/value for given child which will be enforced to
                be kept in list format.
                Usage: force_list={'edit': True} or force_list=('edit') will force edit to be a list even
                when it is a single element
            log_ignored_items - additional parameter to log ignored items in deepdiff. By default, True.
            log_type_mismatch - additional parameter to log mismatched items in deepdiff.
                     By default, False.
            exclude_regex_paths: List of path regexes to exclude in deepdiff.
        :return
        """
        log_ignored_items = kwargs.get("log_ignored_items", True)
        if not isinstance(expected_response, dict):
            raise ValueError(f"expected_response parameter has to be dict not {type(expected_response)}")

        ListMatchOperator.IGNORE_DICTIONARY_ITEM_ADDED = ignore_dictionary_item_added

        custom_operators = self._create_custom_operators(ignore_iterable_item_added)
        response_dict = response
        if not isinstance(response, dict):
            response_dict = self._convert_xml_to_dict(xml_message=response, **kwargs)
        sorted_expected, sorted_response = self._deep_sort(
            expected=expected_response,
            response=response_dict,
            log_type_mismatch=kwargs.get("log_type_mismatch", False),
            exclude_paths=exclude_paths,
        )
        self.validate_regexes_in_expected_response(expected_response=expected_response)
        dd_result = self._create_deep_diff(
            sorted_expected,
            sorted_response,
            expected_response,
            response_dict,
            exclude_paths,
            kwargs.get("exclude_regex_paths", None),
            custom_operators,
        )
        self._handle_ignored_items(
            dd_result=dd_result,
            ignore_dictionary_item_added=ignore_dictionary_item_added,
            ignore_iterable_item_added=ignore_iterable_item_added,
            log_ignored_items=log_ignored_items,
        )
        if dd_result:
            raise RegexDeepDiffException(
                self._create_result_string(
                    response=response_dict,
                    expected=expected_response,
                    matched=False,
                    dd_result=dd_result,
                )
            )
        return response

    def _create_result_string(
        self, response: dict | str, expected: dict, matched: bool = True, dd_result: dict | None = None
    ):
        """
        Method to create common result logs in case of pass or fail. Changes in this method can
        impact methods which parses results from this library (for example TAF).
        :param response: Response that was validated.
        :param expected: Expected response used in valdiation.
        :param matched: Boolean if response was matched with expected response.
        :param dd_result: DeepDiff result in case of mismatch.
        :return:
        """
        response = response if self._is_valid_xml(response) else pprint.pformat(response)
        if matched:
            return f"Reply: {response}\n\nwas matched with expected reply: {pprint.pformat(expected)}"
        result_string = f"Reply: {response}\n\nwas not matched with expected reply: {pprint.pformat(expected)}"
        if dd_result:
            result_string = f"{result_string}\n\nDifferences: {pprint.pformat(dd_result)}"
        return result_string

    def _convert_xml_to_dict(self, xml_message: str, **kwargs) -> dict:
        """
        Method validates that given string is xml and converts it to python dictionary.
        :param xml_message: Message in xml format that will be converted to dict.
        :param kwargs:
            force_list - parameter that will contain tuple or key/value for given child which will be enforced to be
            kept in list format.
            Usage: force_list={'edit': True} or force_list=('edit') will force edit to be a list even when it is a
            single element.
        :return:
        """
        self.validate_xml(xml_message)
        return xmltodict.parse(
            xml_message,
            dict_constructor=dict,
            force_list=kwargs.get("force_list", None),
        )

    @staticmethod
    def validate_xml(xml_data) -> None:
        """Method validates if given string is proper XML data.
        :param xml_data:
        :return:
        """
        try:
            elementTree.fromstring(xml_data)
        except elementTree.ParseError as exc:
            raise RegexDeepDiffException(f"{xml_data} is not proper XML data") from exc

    def _is_valid_xml(self, xml_data: str) -> bool:
        """Check whether provided string can be converted to xml format.
        :param xml_data:
        :return: Boolean is provided string a valid xml
        """
        try:
            self.validate_xml(xml_data)
        except (RegexDeepDiffException, TypeError):
            return False
        return True

    @classmethod
    def validate_regexes_in_expected_response(cls, expected_response: dict) -> None:
        """Validates if expected response contains valid regex patterns."""
        collected_improper_values = []
        for string_value in cls._extract_string_values_from_expected_response(expected_response=expected_response):
            if string_value.startswith("(") and string_value.endswith(")"):
                if not cls._validate_regex_pattern(regex_pattern=string_value):
                    collected_improper_values.append(string_value)
        if collected_improper_values:
            formatted_improper_values = ", ".join(collected_improper_values)
            raise RegexDeepDiffException(
                f"Invalid regex detected in values: {formatted_improper_values}.\n"
                f"Probably invalid usage of parentheses.\n"
                f"Bad example: (?:^ab$)|(?:^cd$)\n"
                f"Good example: ((?:^ab$)|(?:^cd$))"
            )

    @staticmethod
    def _extract_string_values_from_expected_response(expected_response: dict) -> list[str]:
        """Method extracts all string values from expected response."""
        string_values = []

        def recurse(value):
            if isinstance(value, dict):
                for v in value.values():
                    recurse(v)
            elif isinstance(value, list):
                for item in value:
                    recurse(item)
            else:
                if isinstance(value, str):
                    string_values.append(value)

        recurse(expected_response)
        return string_values

    @staticmethod
    def _validate_regex_pattern(regex_pattern: str) -> bool:
        """Check if regex pattern is valid.

        For example, regex_pattern (?:^ab$)|(?:^cd$) is valid from regex perspective, but it is not valid from
        regexdeepdiff perspective when external parentheses are removed (they are used to detect regex).
        When they are removed regex_pattern becomes invalid: ?:^ab$)|(?:^cd$
        User needs to add additional parentheses to make it valid regex ((?:^ab$)|(?:^cd$)).
        """
        try:
            re.compile(regex_pattern[1:-1])
        except re.error:
            return False
        return True
